npm i lucide-react 2>&1 | tail -1 && rm -f src/App.css src/assets/react.svg && mkdir -p src/components src/data src/styles && cat > src/styles/tokens.css <<'EOF'
/* Plume design tokens — warm, rounded, consistent. */
:root {
  color-scheme: light;
  /* surfaces */
  --bg: #f6f3ee;            /* warm paper */
  --surface: #fffdf9;
  --surface-2: #f0ece5;
  --surface-3: #e8e3da;
  --border: rgba(60, 45, 20, 0.08);
  --border-strong: rgba(60, 45, 20, 0.16);
  /* text */
  --ink: #1f1a14;
  --ink-2: #5b544a;
  --ink-3: #8b8377;
  /* accent (used for focus, primary buttons) */
  --accent: #e8712b;
  --accent-ink: #fff;
  --accent-soft: rgba(232, 113, 43, 0.12);
  /* radii */
  --r-xs: 8px;
  --r-sm: 12px;
  --r-md: 16px;
  --r-lg: 22px;
  --r-xl: 28px;
  --r-pill: 999px;
  /* shadows: soft, warm, never grey */
  --shadow-1: 0 1px 2px rgba(60, 40, 10, 0.06), 0 2px 8px rgba(60, 40, 10, 0.05);
  --shadow-2: 0 4px 16px rgba(60, 40, 10, 0.10), 0 1px 3px rgba(60, 40, 10, 0.06);
  --shadow-3: 0 16px 48px rgba(60, 40, 10, 0.18), 0 2px 6px rgba(60, 40, 10, 0.08);
  /* type */
  --font: "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-display: "Segoe UI Variable Display", "Segoe UI", system-ui, sans-serif;
  /* motion */
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-spring: cubic-bezier(0.34, 1.4, 0.64, 1);
  --t-fast: 120ms;
  --t-med: 220ms;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #17140f;
  --surface: #211d17;
  --surface-2: #2a251e;
  --surface-3: #342e26;
  --border: rgba(255, 235, 200, 0.07);
  --border-strong: rgba(255, 235, 200, 0.14);
  --ink: #f3ede4;
  --ink-2: #b8afa2;
  --ink-3: #7e766b;
  --accent: #f28b47;
  --accent-soft: rgba(242, 139, 71, 0.16);
  --shadow-1: 0 1px 2px rgba(0,0,0,0.3), 0 2px 8px rgba(0,0,0,0.25);
  --shadow-2: 0 4px 16px rgba(0,0,0,0.4), 0 1px 3px rgba(0,0,0,0.3);
  --shadow-3: 0 16px 48px rgba(0,0,0,0.6), 0 2px 6px rgba(0,0,0,0.4);
}

/* Account hues: each account gets a two-stop gradient, like the Google app icons. */
.hue-coral   { --a1: #ff7a59; --a2: #ff3d6e; }
.hue-sun     { --a1: #ffc83d; --a2: #ff8a00; }
.hue-leaf    { --a1: #5fd36b; --a2: #12a05a; }
.hue-sky     { --a1: #5ab4ff; --a2: #2a6cf6; }
.hue-grape   { --a1: #b68cff; --a2: #7a3ff2; }
.hue-mint    { --a1: #62e6d4; --a2: #16a99b; }
.hue-rose    { --a1: #ff9ad0; --a2: #e6399b; }
.hue-slate   { --a1: #9aa8bd; --a2: #4a5b78; }
EOF
