@import "./tokens.css";

*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
body {
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  user-select: none;
}
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
input, textarea { font: inherit; color: inherit; }
::selection { background: var(--accent-soft); }

/* scrollbars: slim + warm */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 99px; border: 3px solid transparent; background-clip: padding-box; }
::-webkit-scrollbar-thumb:hover { background: var(--ink-3); background-clip: padding-box; border: 3px solid transparent; }
::-webkit-scrollbar-track { background: transparent; }

.icon-btn {
  display: inline-grid; place-items: center;
  width: 36px; height: 36px; border-radius: var(--r-sm);
  color: var(--ink-2);
  transition: background var(--t-fast) var(--ease), color var(--t-fast), transform var(--t-fast) var(--ease-spring);
}
.icon-btn:hover { background: var(--surface-2); color: var(--ink); }
.icon-btn:active { transform: scale(0.94); }

.pill {
  display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 14px; border-radius: var(--r-pill);
  color: var(--ink-2); font-weight: 500;
  transition: background var(--t-fast) var(--ease), color var(--t-fast);
}
.pill:hover { background: var(--surface-2); color: var(--ink); }
.pill[data-active="true"] { background: var(--ink); color: var(--bg); }

.avatar {
  display: grid; place-items: center; flex-shrink: 0;
  border-radius: 38%;
  background: linear-gradient(135deg, var(--a1), var(--a2));
  color: #fff; font-weight: 700; letter-spacing: -0.02em;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.35), inset 0 -2px 4px rgba(0,0,0,0.12);
}
EOF
