import { Inbox, Plus, Settings } from "lucide-react";
import type { Account } from "../data/mock";
import { Avatar } from "./Avatar";
import "./AccountRail.css";

interface Props {
  accounts: Account[];
  selected: string | "all";
  onSelect: (id: string | "all") => void;
  onAdd: () => void;
}

export function AccountRail({ accounts, selected, onSelect, onAdd }: Props) {
  const totalUnread = accounts.reduce((n, a) => n + a.unread, 0);
  return (
    <nav className="rail">
      <div className="rail-logo" title="Plume">
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none">
          <path d="M20 3c-6 0-11 4-13 10l-3 8 8-3c6-2 10-7 10-13V3z" fill="url(#plume-g)" />
          <path d="M6 18l7-7" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" opacity=".8" />
          <defs>
            <linearGradient id="plume-g" x1="4" y1="20" x2="20" y2="4">
              <stop stopColor="#ff8a3d" />
              <stop offset="1" stopColor="#ff3d6e" />
            </linearGradient>
          </defs>
        </svg>
      </div>

      <button className="rail-item" data-active={selected === "all"} onClick={() => onSelect("all")} title="All inboxes">
        <span className="rail-all"><Inbox size={18} strokeWidth={2.2} /></span>
        {totalUnread > 0 && <span className="rail-badge">{totalUnread}</span>}
      </button>

      <div className="rail-sep" />

      <div className="rail-list">
        {accounts.map((a) => (
          <button key={a.id} className="rail-item" data-active={selected === a.id} onClick={() => onSelect(a.id)} title={a.name + " · " + a.email}>
            <Avatar name={a.name} hue={a.hue} size={40} />
            {a.unread > 0 && <span className="rail-badge">{a.unread}</span>}
            {a.owner === "friend" && <span className="rail-friend" title="Friend's account" />}
          </button>
        ))}
        <button className="rail-item rail-add" onClick={onAdd} title="Add account or sign in with Google">
          <span className="rail-plus"><Plus size={20} strokeWidth={2.4} /></span>
        </button>
      </div>

      <button className="icon-btn rail-settings" title="Settings"><Settings size={19} /></button>
    </nav>
  );
}

