input.content:
.rail {
  width: 72px; height: 100%;
  display: flex; flex-direction: column; align-items: center;
  padding: 14px 0 12px; gap: 6px;
  background: var(--bg);
}
.rail-logo { display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: 6px; }
.rail-sep { width: 28px; height: 1px; background: var(--border-strong); margin: 6px 0; }
.rail-list { display: flex; flex-direction: column; gap: 6px; flex: 1; overflow-y: auto; padding: 4px 0; scrollbar-width: none; }
.rail-list::-webkit-scrollbar { display: none; }

.rail-item {
  position: relative; display: grid; place-items: center;
  width: 52px; height: 52px; border-radius: var(--r-md);
  transition: background var(--t-fast) var(--ease);
}
.rail-item:hover { background: var(--surface-2); }
.rail-item:hover .avatar, .rail-item:hover .rail-all, .rail-item:hover .rail-plus { transform: scale(1.06); }
.rail-item:active .avatar { transform: scale(0.96); }
.rail-item .avatar, .rail-all, .rail-plus { transition: transform var(--t-med) var(--ease-spring), box-shadow var(--t-med); }
.rail-item[data-active="true"]::before {
  content: ""; position: absolute; left: -10px; top: 14px; bottom: 14px; width: 4px;
  border-radius: 99px; background: var(--ink);
}
.rail-item[data-active="true"] .avatar { box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--ink), inset 0 1px 0 rgba(255,255,255,.35); }

.rail-all {
  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 38%;
  background: var(--surface-3); color: var(--ink);
}
.rail-item[data-active="true"] .rail-all { background: var(--ink); color: var(--bg); }

.rail-plus {
  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 38%;
  border: 2px dashed var(--border-strong); color: var(--ink-3);
}
.rail-add:hover .rail-plus { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }

.rail-badge {
  position: absolute; top: 4px; right: 4px;
  min-width: 18px; height: 18px; padding: 0 5px; border-radius: 99px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 11px; font-weight: 700; line-height: 18px; text-align: center;
  box-shadow: 0 0 0 2px var(--bg);
}
.rail-friend {
  position: absolute; bottom: 5px; right: 6px; width: 9px; height: 9px; border-radius: 50%;
  background: var(--ink-3); box-shadow: 0 0 0 2px var(--bg);
}
.rail-settings { margin-top: auto; }

