input.content:
.list {
  width: 400px; min-width: 340px; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface);
  border-radius: var(--r-xl) 0 0 var(--r-xl);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.list-head { padding: 22px 18px 10px; display: flex; flex-direction: column; gap: 12px; }
.list-title-row { display: flex; align-items: center; justify-content: space-between; }
.list-title { margin: 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }

.compose {
  display: inline-flex; align-items: center; gap: 8px;
  height: 36px; padding: 0 14px 0 12px; border-radius: var(--r-pill);
  background: var(--ink); color: var(--bg); font-weight: 600;
  box-shadow: var(--shadow-1);
  transition: transform var(--t-med) var(--ease-spring), box-shadow var(--t-med);
}
.compose:hover { transform: translateY(-1px); box-shadow: var(--shadow-2); }
.compose:active { transform: scale(0.97); }

.search {
  display: flex; align-items: center; gap: 10px;
  height: 40px; padding: 0 14px; border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  transition: box-shadow var(--t-fast), background var(--t-fast);
}
.search:focus-within { background: var(--surface); box-shadow: 0 0 0 2px var(--accent); color: var(--ink-2); }
.search input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); }
.search input::placeholder { color: var(--ink-3); }

.folders { display: flex; gap: 4px; }

.list-scroll { flex: 1; overflow-y: auto; padding: 4px 10px 16px; }
.list-empty { padding: 60px 20px; text-align: center; color: var(--ink-3); }

.row {
  position: relative; width: 100%; text-align: left;
  display: flex; gap: 12px; align-items: flex-start;
  padding: 12px 12px; border-radius: var(--r-md);
  transition: background var(--t-fast) var(--ease);
}
.row:hover { background: var(--surface-2); }
.row[data-selected="true"] { background: var(--surface-3); }
.row-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.row-top { display: flex; align-items: center; gap: 8px; }
.row-from { font-weight: 600; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-from { color: var(--ink); }
.row-time { font-size: 12px; color: var(--ink-3); flex-shrink: 0; }
.row-chip {
  font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 99px; flex-shrink: 0;
  color: var(--a2); background: color-mix(in srgb, var(--a1) 18%, transparent);
}
.row-subject { font-weight: 500; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-subject { font-weight: 700; color: var(--ink); }
.row-preview { font-size: 13px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-star { position: absolute; right: 14px; bottom: 14px; color: #f2b234; }
.row-dot { position: absolute; left: 4px; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: 50%; background: var(--accent); }

