input.content:
import { useState } from "react";
import { X, Link2, Mail, ArrowRight, ShieldCheck } from "lucide-react";
import type { Account } from "../data/mock";
import { Avatar } from "./Avatar";
import "./AddSheet.css";

interface Props {
  accounts: Account[];
  onClose: () => void;
}

type Tab = "signin" | "add";

function looksLikeGoogleAuth(url: string) {
  try {
    const u = new URL(url.trim());
    return u.hostname === "accounts.google.com" && u.pathname.includes("/o/oauth2");
  } catch {
    return false;
  }
}

export function AddSheet({ accounts, onClose }: Props) {
  const [tab, setTab] = useState<Tab>("signin");
  const [url, setUrl] = useState("");
  const [picked, setPicked] = useState<string | null>(null);
  const valid = looksLikeGoogleAuth(url);
  const google = accounts.filter((a) => a.provider === "gmail");

  return (
    <div className="sheet-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="sheet" role="dialog" aria-modal>
        <header className="sheet-head">
          <div className="sheet-tabs">
            <button className="pill" data-active={tab === "signin"} onClick={() => setTab("signin")}>
              <ShieldCheck size={15} /> Sign in with Google
            </button>
            <button className="pill" data-active={tab === "add"} onClick={() => setTab("add")}>
              <Mail size={15} /> Add account
            </button>
          </div>
          <button className="icon-btn" onClick={onClose} title="Close"><X size={18} /></button>
        </header>

        {tab === "signin" && (
          <div className="sheet-body">
            <h2 className="sheet-title">Which account should sign in?</h2>
            <p className="sheet-hint">
              Paste the Google sign-in link a site or app just opened. UniMail finishes the login with the account you pick and
              hands the result back to your browser, so nothing else changes.
            </p>
            <label className="sheet-field" data-valid={url ? valid : undefined}>
              <Link2 size={16} />
              <input
                autoFocus
                placeholder="https://accounts.google.com/o/oauth2/..."
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                spellCheck={false}
              />
            </label>

            <div className="sheet-grid">
              {google.map((a) => (
                <button key={a.id} className="acct" data-picked={picked === a.id} onClick={() => setPicked(a.id)}>
                  <Avatar name={a.name} hue={a.hue} size={44} />
                  <div className="acct-text">
                    <div className="acct-name">{a.name}{a.owner === "friend" && <span className="acct-tag">friend</span>}</div>
                    <div className="acct-email">{a.email}</div>
                  </div>
                </button>
              ))}
            </div>

            <button className="primary" disabled={!valid || !picked}>
              Continue <ArrowRight size={16} />
            </button>
          </div>
        )}

        {tab === "add" && (
          <div className="sheet-body">
            <h2 className="sheet-title">Connect a mailbox</h2>
            <p className="sheet-hint">Gmail, Outlook, iCloud, or any IMAP host. It stays signed in until you remove it.</p>
