.sheet-backdrop {
  position: fixed; inset: 0; z-index: 50;
  display: grid; place-items: center;
  background: rgba(30, 20, 10, 0.32);
  backdrop-filter: blur(6px);
  animation: fade var(--t-med) var(--ease);
}
@keyframes fade { from { opacity: 0; } }
@keyframes pop { from { opacity: 0; transform: translateY(14px) scale(0.98); } }

.sheet {
  width: 560px; max-width: calc(100vw - 40px);
  background: var(--surface); border-radius: var(--r-xl);
  box-shadow: var(--shadow-3);
  animation: pop 260ms var(--ease-spring);
  overflow: hidden;
}
.sheet-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 14px 0 18px; }
.sheet-tabs { display: flex; gap: 4px; }
.sheet-body { padding: 18px 26px 26px; display: flex; flex-direction: column; gap: 14px; }
.sheet-title { margin: 6px 0 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }
.sheet-hint { margin: 0; color: var(--ink-2); line-height: 1.5; }

.sheet-field {
  display: flex; align-items: center; gap: 10px;
  height: 44px; padding: 0 14px; border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  transition: box-shadow var(--t-fast), background var(--t-fast);
}
.sheet-field:focus-within { background: var(--surface); box-shadow: 0 0 0 2px var(--accent); }
.sheet-field[data-valid="true"] { box-shadow: 0 0 0 2px #2fb36b; }
.sheet-field[data-valid="false"] { box-shadow: 0 0 0 2px #e5484d; }
.sheet-field input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); font-size: 13px; }

.sheet-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.acct {
  display: flex; align-items: center; gap: 12px; text-align: left;
  padding: 10px 12px; border-radius: var(--r-md);
  background: var(--surface-2);
  border: 2px solid transparent;
  transition: border-color var(--t-fast), background var(--t-fast), transform var(--t-med) var(--ease-spring);
}
.acct:hover { background: var(--surface-3); }
.acct:active { transform: scale(0.98); }
.acct[data-picked="true"] { border-color: var(--ink); background: var(--surface); }
.acct-text { min-width: 0; }
.acct-name { font-weight: 700; display: flex; align-items: center; gap: 6px; }
.acct-tag { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--ink-3); background: var(--surface-3); padding: 1px 6px; border-radius: 99px; }
.acct-email { font-size: 12px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.primary {
  align-self: flex-end;
  display: inline-flex; align-items: center; gap: 8px;
  height: 42px; padding: 0 18px 0 20px; border-radius: var(--r-pill);
  background: var(--accent); color: var(--accent-ink); font-weight: 600;
  box-shadow: var(--shadow-1);
  transition: transform var(--t-med) var(--ease-spring), opacity var(--t-fast);
}
.primary:hover { transform: translateY(-1px); }
.primary:disabled { opacity: 0.4; cursor: not-allowed; transform: none; }

.providers { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.provider {
  display: flex; align-items: center; gap: 12px;
  height: 56px; padding: 0 16px; border-radius: var(--r-md);
  background: var(--surface-2); font-weight: 600;
  transition: background var(--t-fast), transform var(--t-med) var(--ease-spring);
}
.provider:hover { background: var(--surface-3); transform: translateY(-1px); }
.provider-dot { width: 22px; height: 22px; border-radius: 38%; background: linear-gradient(135deg, var(--a1), var(--a2)); }

