/* The OS window is transparent and frameless; .frame draws the real window. */
.frame {
  height: 100%;
  padding: 10px;                 /* room for the shadow */
  background: transparent;
}
.frame[data-maximized="true"] { padding: 0; }

.app {
  position: relative;
  display: flex; height: 100%;
  background: var(--bg);
  border-radius: 18px;
  box-shadow: 0 10px 40px rgba(30, 18, 5, 0.35), 0 0 0 1px rgba(60, 45, 20, 0.10);
  overflow: hidden;
}
.frame[data-maximized="true"] .app { border-radius: 0; box-shadow: none; }

.main {
  flex: 1; min-width: 0; height: 100%;
  display: flex;
  padding: 10px 10px 10px 0;
}
.main > .list { border-radius: var(--r-xl) 0 0 var(--r-xl); }
.main > .reader { border-radius: 0 var(--r-xl) var(--r-xl) 0; }

/* anything marked as a drag region moves the window */
[data-tauri-drag-region] { -webkit-app-region: drag; }
[data-tauri-drag-region] button, [data-tauri-drag-region] input { -webkit-app-region: no-drag; }

