export type Hue = "coral" | "sun" | "leaf" | "sky" | "grape" | "mint" | "rose" | "slate";

export interface Account {
  id: string;
  name: string;
  email: string;
  provider: "gmail" | "outlook" | "imap";
  hue: Hue;
  unread: number;
  owner?: "me" | "friend";
}

export interface Message {
  id: string;
  threadId: string;
  accountId: string;
  from: { name: string; email: string };
  subject: string;
  preview: string;
  body: string;
  date: string; // ISO
  unread: boolean;
  starred: boolean;
  folder: "inbox" | "starred" | "sent" | "archive";
