import { useEffect, useState } from "react";
import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
import type { Account, Message } from "../data/mock";
import { Avatar } from "./Avatar";
import { relTime } from "./MailList";
import "./Reader.css";

interface Props {
  /** All messages in the open conversation, newest first. */
  thread: Message[];
  account: Account | null;
}

/** Bodies longer than this start clipped with a "Show more" control. */
const CLIP_CHARS = 420;

export function Reader({ thread, account }: Props) {
  const newest = thread[0];
  // Which messages are expanded. The newest is open by default; older ones start collapsed.
  const [open, setOpen] = useState<Set<string>>(new Set());
  useEffect(() => {
    setOpen(new Set(newest ? [newest.id] : []));
  }, [newest?.threadId]);

  if (!newest || !account) {
    return (
      <section className="reader reader-empty">
        <div className="reader-empty-art">
          <MailOpen size={38} strokeWidth={1.6} />
        </div>
        <p>Pick a message to read it here.</p>
      </section>
    );
  }

  const toggle = (id: string) =>
    setOpen((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  return (
    <section className="reader">
      <header className="reader-bar">
        <div className={"reader-account hue-" + account.hue}>
          <Avatar name={account.name} hue={account.hue} size={22} />
          <span>{account.email}</span>
        </div>
        <div className="reader-actions">
          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
          <button className="icon-btn" title="Star"><Star size={18} /></button>
          <button className="icon-btn" title="Archive"><Archive size={18} /></button>
          <button className="icon-btn" title="Delete"><Trash2 size={18} /></button>
        </div>
      </header>

      <div className="thread">
        <div className="thread-head">
          <h2 className="reader-subject">{newest.subject}</h2>
          {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
        </div>

        {thread.map((m) => (
          <MessageCard key={m.id} message={m} hue={account.hue} expanded={open.has(m.id)} onToggle={() => toggle(m.id)} />
        ))}
      </div>
    </section>
  );
}

function MessageCard({ message: m, hue, expanded, onToggle }: { message: Message; hue: Account["hue"]; expanded: boolean; onToggle: () => void }) {
  const [showAll, setShowAll] = useState(false);
  const long = m.body.length > CLIP_CHARS;
  const date = new Date(m.date);

  return (
    <article className="msg" data-expanded={expanded}>
      <button className="msg-head" onClick={onToggle}>
        <Avatar name={m.from.name} hue={hue} size={40} />
        <div className="msg-who">
          <div className="msg-name">{m.from.name}</div>
          {expanded
            ? <div className="msg-email">{m.from.email}</div>
            : <div className="msg-snippet">{m.preview}</div>}
        </div>
        <div className="msg-when" title={date.toLocaleString()}>
          {expanded
            ? date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) + " · " + date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })
            : relTime(m.date)}
        </div>
        <ChevronDown size={16} className="msg-chevron" />
      </button>

      {expanded && (
        <div className="msg-body-wrap" data-clipped={long && !showAll}>
          <div className="msg-body">{m.body}</div>
          {long && (
            <button className="msg-more" onClick={() => setShowAll((v) => !v)}>
              {showAll ? "Show less" : "Show more"}
            </button>
          )}
        </div>
      )}
    </article>
  );
}

.reader {
  flex: 1; min-width: 0; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface-2);
  overflow: hidden;
}
.reader-empty { align-items: center; justify-content: center; gap: 14px; color: var(--ink-3); }
.reader-empty-art {
  display: grid; place-items: center; width: 84px; height: 84px; border-radius: 28%;
  background: var(--surface); color: var(--ink-3); box-shadow: var(--shadow-1);
}

.reader-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 20px 6px;
}
.reader-account {
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 12px 0 5px; border-radius: var(--r-pill);
  background: var(--surface); color: var(--ink-2); font-size: 13px; font-weight: 500;
  box-shadow: var(--shadow-1);
}
.reader-actions { display: flex; gap: 2px; margin-right: 112px; }

/* The conversation: a flat scrolling column, messages are the only cards. */
.thread {
  flex: 1; overflow-y: auto;
  padding: 10px 24px 28px;
  display: flex; flex-direction: column; gap: 10px;
}
.thread-head { display: flex; align-items: baseline; gap: 12px; padding: 8px 4px 10px; }
.reader-subject { margin: 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.25; user-select: text; }
.thread-count { font-size: 12px; color: var(--ink-3); white-space: nowrap; }

.msg {
  background: var(--surface); border-radius: var(--r-xl);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.msg-head {
  width: 100%; text-align: left;
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px;
  transition: background var(--t-fast);
}
.msg[data-expanded="false"] .msg-head:hover { background: var(--surface-2); }
.msg-who { flex: 1; min-width: 0; }
.msg-name { font-weight: 700; }
.msg-email { font-size: 12px; color: var(--ink-3); }
.msg-snippet { font-size: 13px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg-when { font-size: 12px; color: var(--ink-3); white-space: nowrap; }
.msg-chevron { color: var(--ink-3); flex-shrink: 0; transition: transform var(--t-med) var(--ease); }
.msg[data-expanded="true"] .msg-chevron { transform: rotate(180deg); }

.msg-body-wrap { position: relative; padding: 4px 20px 18px 68px; }
.msg-body {
  white-space: pre-wrap; font-size: 15px; line-height: 1.65; color: var(--ink);
  max-width: 68ch; user-select: text;
}
.msg-body-wrap[data-clipped="true"] .msg-body {
  max-height: 9.5em; overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent);
  mask-image: linear-gradient(to bottom, #000 55%, transparent);
}
.msg-more {
  margin-top: 6px; height: 30px; padding: 0 12px; border-radius: var(--r-pill);
  background: var(--surface-2); color: var(--ink-2); font-weight: 600; font-size: 13px;
  transition: background var(--t-fast), color var(--t-fast);
}
.msg-more:hover { background: var(--surface-3); color: var(--ink); }

import { useMemo, useState } from "react";
import { accounts, messages, type Message } from "./data/mock";
import { AccountRail } from "./components/AccountRail";
import { MailList } from "./components/MailList";
import { Reader } from "./components/Reader";
import { AddSheet } from "./components/AddSheet";
import { WindowControls, useMaximized, useWindowDrag } from "./components/WindowControls";
import "./styles/base.css";
import "./App.css";

type Folder = Message["folder"];

export default function App() {
  const [selectedAccount, setSelectedAccount] = useState<string | "all">("all");
  const [folder, setFolder] = useState<Folder>("inbox");
  const [selectedThread, setSelectedThread] = useState<string | null>(null);
  const [sheet, setSheet] = useState(false);
  const maximized = useMaximized();
  useWindowDrag();

  const accountsById = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a])), []);

  // Messages that belong to the current account + folder, newest first.
  const scoped = useMemo(() => {
    return messages
      .filter((m) => selectedAccount === "all" || m.accountId === selectedAccount)
      .filter((m) => (folder === "starred" ? m.starred : m.folder === folder))
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [selectedAccount, folder]);

  // The list shows one row per conversation: its newest message, plus how many are in it.
  const rows = useMemo(() => {
    const seen = new Map<string, { latest: Message; count: number; unread: boolean }>();
    for (const m of scoped) {
      const t = seen.get(m.threadId);
      if (t) { t.count += 1; t.unread ||= m.unread; }
      else seen.set(m.threadId, { latest: m, count: 1, unread: m.unread });
    }
    return [...seen.values()];
  }, [scoped]);

  const thread = useMemo(
    () => (selectedThread ? scoped.filter((m) => m.threadId === selectedThread) : []),
    [scoped, selectedThread],
  );
  const account = thread[0] ? accountsById[thread[0].accountId] : null;
  const title = selectedAccount === "all" ? "All inboxes" : accountsById[selectedAccount].name;

  return (
    <div className="frame" data-maximized={maximized}>
      <div className="app">
        <WindowControls maximized={maximized} />
        <AccountRail
          accounts={accounts}
          selected={selectedAccount}
          onSelect={(id) => { setSelectedAccount(id); setSelectedThread(null); }}
          onAdd={() => setSheet(true)}
        />
        <main className="main">
          <MailList
            title={title}
            accountsById={accountsById}
            rows={rows}
            folder={folder}
            onFolder={setFolder}
            selectedId={selectedThread}
            onSelect={setSelectedThread}
            showAccountChip={selectedAccount === "all"}
          />
          <Reader thread={thread} account={account} />
        </main>
        {sheet && <AddSheet accounts={accounts} onClose={() => setSheet(false)} />}
      </div>
    </div>
  );
}

