.reader {
  flex: 1; min-width: 0; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface-2);
  overflow: hidden;
}
.reader-empty { align-items: center; justify-content: center; gap: 14px; color: var(--ink-3); }
.reader-empty-art {
  display: grid; place-items: center; width: 84px; height: 84px; border-radius: 28%;
  background: var(--surface); color: var(--ink-3); box-shadow: var(--shadow-1);
}

.reader-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 20px 6px;
}
.reader-account {
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 12px 0 5px; border-radius: var(--r-pill);
  background: var(--surface); color: var(--ink-2); font-size: 13px; font-weight: 500;
  box-shadow: var(--shadow-1);
}
.reader-actions { display: flex; gap: 2px; margin-right: 112px; }

/* The conversation: a flat scrolling column, messages are the only cards. */
.thread {
  flex: 1; overflow-y: auto;
  padding: 10px 24px 28px;
  display: flex; flex-direction: column; gap: 10px;
}
.thread-head { display: flex; align-items: baseline; gap: 12px; padding: 8px 4px 10px; }
.reader-subject { margin: 0; font-family: var(--font-display); font-size: 22px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.25; user-select: text; }
.thread-count { font-size: 12px; color: var(--ink-3); white-space: nowrap; }

.msg {
  background: var(--surface); border-radius: var(--r-xl);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.msg-head {
  width: 100%; text-align: left;
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px;
  transition: background var(--t-fast);
}
.msg[data-expanded="false"] .msg-head:hover { background: var(--surface-2); }
.msg-who { flex: 1; min-width: 0; }
.msg-name { font-weight: 700; }
.msg-email { font-size: 12px; color: var(--ink-3); }
.msg-snippet { font-size: 13px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg-when { font-size: 12px; color: var(--ink-3); white-space: nowrap; }
.msg-chevron { color: var(--ink-3); flex-shrink: 0; transition: transform var(--t-med) var(--ease); }
.msg[data-expanded="true"] .msg-chevron { transform: rotate(180deg); }

.msg-body-wrap { position: relative; padding: 4px 20px 18px 68px; }
.msg-body {
  white-space: pre-wrap; font-size: 15px; line-height: 1.65; color: var(--ink);
  max-width: 68ch; user-select: text;
}
.msg-body-wrap[data-clipped="true"] .msg-body {
  max-height: 9.5em; overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent);
  mask-image: linear-gradient(to bottom, #000 55%, transparent);
}
.msg-more {
  margin-top: 6px; height: 30px; padding: 0 12px; border-radius: var(--r-pill);
  background: var(--surface-2); color: var(--ink-2); font-weight: 600; font-size: 13px;
  transition: background var(--t-fast), color var(--t-fast);
}
.msg-more:hover { background: var(--surface-3); color: var(--ink); }

