use tauri::{PhysicalPosition, Window};

/// Un-maximize the window, place it so the cursor sits at the same relative spot it was
/// grabbed at, and hand it to the OS move loop. All in one step on the window thread, so
/// the pointer can't drift between placing the window and starting the drag.
///
/// `fx` is the horizontal grab point as a fraction of the maximized width (0..1);
/// `grab_y` is the grab point's distance from the window top in physical pixels.
#[tauri::command]
fn restore_and_drag(window: Window, fx: f64, grab_y: f64) -> Result<(), String> {
    let err = |e: tauri::Error| e.to_string();
    window.unmaximize().map_err(err)?;
    let size = window.outer_size().map_err(err)?;
    let cursor = window.cursor_position().map_err(err)?;
    let x = cursor.x - fx * size.width as f64;
    let y = cursor.y - grab_y.min(size.height as f64 * 0.5);
    window
        .set_position(PhysicalPosition::new(x.round() as i32, y.round() as i32))
        .map_err(err)?;
    window.start_dragging().map_err(err)
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![restore_and_drag])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

