1	use tauri::Window;
2	
3	/// Turn the desktop compositor's restore/minimize animation on or off for this window.
4	/// While a user is dragging a maximized window we want it to snap to size instantly
5	/// so the OS drag can track the pointer without a visible pause.
6	#[cfg(windows)]
7	fn set_dwm_transitions(window: &Window, enabled: bool) {
8	    use windows::core::BOOL;
9	    use windows::Win32::Foundation::HWND;
10	    use windows::Win32::Graphics::Dwm::{DwmSetWindowAttribute, DWMWA_TRANSITIONS_FORCEDISABLED};
11	    if let Ok(hwnd) = window.hwnd() {
12	        let disabled = BOOL::from(!enabled);
13	        unsafe {
14	            let _ = DwmSetWindowAttribute(
15	                HWND(hwnd.0),
16	                DWMWA_TRANSITIONS_FORCEDISABLED,
17	                &disabled as *const BOOL as *const _,
18	                std::mem::size_of::<BOOL>() as u32,
19	            );
20	        }
21	    }
22	}
23	
24	/// Restore the maximized window straight into a rectangle positioned under the cursor.
25	/// One `SetWindowPlacement` call does both the un-maximize and the move, so the window
26	/// paints exactly once, already in the right place. No flicker, no catch-up jump.
27	#[cfg(windows)]
28	fn restore_under_cursor(window: &Window, fx: f64, grab_y: f64) -> Result<(), String> {
29	    use windows::Win32::Foundation::{HWND, POINT, RECT};
30	    use windows::Win32::UI::WindowsAndMessaging::{
31	        GetCursorPos, GetWindowPlacement, SetWindowPlacement, SystemParametersInfoW,
32	        SPI_GETWORKAREA, SW_SHOWNORMAL, SYSTEM_PARAMETERS_INFO_UPDATE_FLAGS, WINDOWPLACEMENT,
33	    };
34	    let e = |err: windows::core::Error| err.to_string();
35	    let hwnd = HWND(window.hwnd().map_err(|x| x.to_string())?.0);
36	    unsafe {
37	        let mut wp = WINDOWPLACEMENT { length: std::mem::size_of::<WINDOWPLACEMENT>() as u32, ..Default::default() };
38	        GetWindowPlacement(hwnd, &mut wp).map_err(e)?;
39	        let w = wp.rcNormalPosition.right - wp.rcNormalPosition.left;
40	        let h = wp.rcNormalPosition.bottom - wp.rcNormalPosition.top;
41	
42	        let mut cursor = POINT::default();
43	        GetCursorPos(&mut cursor).map_err(e)?;
44	
45	        // rcNormalPosition is in workspace coordinates (excludes the taskbar area).
46	        let mut work = RECT::default();
47	        SystemParametersInfoW(SPI_GETWORKAREA, 0, Some(&mut work as *mut RECT as *mut _), SYSTEM_PARAMETERS_INFO_UPDATE_FLAGS(0)).map_err(e)?;
48	
49	        let x = (cursor.x as f64 - fx * w as f64).round() as i32 - work.left;
50	        let y = (cursor.y as f64 - grab_y.min(h as f64 * 0.5)).round() as i32 - work.top;
51	        wp.rcNormalPosition = RECT { left: x, top: y, right: x + w, bottom: y + h };
52	        wp.showCmd = SW_SHOWNORMAL.0 as u32;
53	        SetWindowPlacement(hwnd, &wp).map_err(e)?;
54	    }
55	    Ok(())
56	}
57	
58	#[cfg(not(windows))]
59	fn set_dwm_transitions(_window: &Window, _enabled: bool) {}
60	
61	#[cfg(not(windows))]
62	fn restore_under_cursor(window: &Window, fx: f64, grab_y: f64) -> Result<(), String> {
63	    let err = |e: tauri::Error| e.to_string();
64	    window.unmaximize().map_err(err)?;
65	    let size = window.outer_size().map_err(err)?;
66	    let cursor = window.cursor_position().map_err(err)?;
67	    let x = cursor.x - fx * size.width as f64;
68	    let y = cursor.y - grab_y.min(size.height as f64 * 0.5);
69	    window
70	        .set_position(tauri::PhysicalPosition::new(x.round() as i32, y.round() as i32))
71	        .map_err(err)
72	}
73	
74	/// Un-maximize the window under the cursor and hand it to the OS move loop, all in one
75	/// step on the window thread so the pointer can't drift in between.
76	///
77	/// `fx` is the horizontal grab point as a fraction of the maximized width (0..1);
78	/// `grab_y` is the grab point's distance from the window top in physical pixels.
79	#[tauri::command]
80	fn restore_and_drag(window: Window, fx: f64, grab_y: f64) -> Result<(), String> {
81	    restore_under_cursor(&window, fx, grab_y)?;
82	    window.start_dragging().map_err(|e| e.to_string())
83	}
