92	            // only gets in the way of the drag-to-restore gesture. Off for good.
93	            if let Some(w) = app.get_window("main") {
94	                set_dwm_transitions(&w, false);
95	            }
96	            Ok(())
97	        })
98	        .invoke_handler(tauri::generate_handler![restore_and_drag])
99	        .run(tauri::generate_context!())
