input.content:
/* UniMail design tokens. Dark only. */
:root {
  /* Surfaces: four clearly separated steps, warm-neutral. */
  --bg: #111010;          /* window + rail */
  --surface: #1a1918;     /* list / reader base */
  --surface-2: #242221;   /* cards, inputs, hover */
  --surface-3: #2f2c2a;   /* pressed / selected / raised */
  --border: rgba(255, 240, 220, 0.06);
  --border-strong: rgba(255, 240, 220, 0.12);

  /* Text */
  --ink: #ece7df;
  --ink-2: #aaa39a;
  --ink-3: #6f6a63;

  /* Accent: one muted orange for the few things that need to shout. */
  --accent: #d9803f;
  --accent-ink: #1a120a;
  --accent-soft: rgba(217, 128, 63, 0.14);

  /* Radius scale. Outer surfaces are larger, inner controls smaller. */
  --r-xs: 6px;
  --r-sm: 8px;
  --r-md: 10px;
  --r-lg: 12px;
  --r-xl: 14px;
  --r-pill: 999px;

  /* Spacing scale */
  --s-1: 4px;
  --s-2: 8px;
  --s-3: 12px;
  --s-4: 16px;
  --s-5: 20px;
  --s-6: 24px;

  /* Shadows: subtle, used for lift only */
  --shadow-1: 0 1px 2px rgba(0,0,0,0.35);
  --shadow-2: 0 4px 14px rgba(0,0,0,0.4);
  --shadow-3: 0 16px 48px rgba(0,0,0,0.6);

  /* Type */
  --font: "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-display: "Segoe UI Variable Display", "Segoe UI", system-ui, sans-serif;

  /* Motion */
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-spring: cubic-bezier(0.34, 1.3, 0.64, 1);
  --t-fast: 120ms;
  --t-med: 200ms;
}

/* Account hues. Muted two-stop gradients: enough to tell accounts apart, not neon. */
.hue-coral   { --a1: #d9705f; --a2: #b84a55; }
.hue-sun     { --a1: #d4a04a; --a2: #b6752f; }
.hue-leaf    { --a1: #6aa870; --a2: #3f7f52; }
.hue-sky     { --a1: #5f8fd0; --a2: #3f63ad; }
.hue-grape   { --a1: #9a82cf; --a2: #6c56aa; }
.hue-mint    { --a1: #5faea3; --a2: #3a8079; }
.hue-rose    { --a1: #c98aae; --a2: #a3568a; }
.hue-slate   { --a1: #8c96a6; --a2: #5a6678; }

