  width: 36px; height: 36px; border-radius: var(--r-sm);
  color: var(--ink-2);
  transition: background var(--t-fast) var(--ease), color var(--t-fast), transform var(--t-fast) var(--ease-spring);
}
.icon-btn:hover { background: var(--surface-2); color: var(--ink); }
.icon-btn:active { transform: scale(0.94); }

.pill {
  display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 14px; border-radius: var(--r-pill);
  color: var(--ink-2); font-weight: 500;
  transition: background var(--t-fast) var(--ease), color var(--t-fast);
}
.pill:hover { background: var(--surface-2); color: var(--ink); }
.pill[data-active="true"] { background: var(--ink); color: var(--bg); }

.avatar {
  display: grid; place-items: center; flex-shrink: 0;
  border-radius: 28%;
  background: linear-gradient(135deg, var(--a1), var(--a2));
  color: #fff; font-weight: 700; letter-spacing: -0.02em;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.35), inset 0 -2px 4px rgba(0,0,0,0.12);
}

input.content:
/* The OS window is transparent and frameless; .app is the visible rounded window. */
.frame { height: 100%; padding: 0; background: transparent; }

.app {
  position: relative;
  display: flex; height: 100%;
  background: var(--bg);
  border-radius: 12px;
  overflow: hidden;
}
.frame[data-maximized="true"] .app { border-radius: 0; }

.main {
  flex: 1; min-width: 0; height: 100%;
  display: flex;
  padding: var(--s-2) var(--s-2) var(--s-2) 0;
  gap: 1px; /* hairline between list and reader */
}
.main > .list { border-radius: var(--r-xl) 0 0 var(--r-xl); }
.main > .reader { border-radius: 0 var(--r-xl) var(--r-xl) 0; }

.rail {
  width: 64px; height: 100%;
  display: flex; flex-direction: column; align-items: center;
  padding: var(--s-3) 0 var(--s-3); gap: var(--s-1);
  background: var(--bg);
}
.rail-logo { display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: var(--s-1); }
.rail-logo img { pointer-events: none; width: 26px; height: 26px; }
.rail-sep { width: 24px; height: 1px; background: var(--border-strong); margin: var(--s-1) 0; }
.rail-list { display: flex; flex-direction: column; gap: var(--s-1); flex: 1; overflow-y: auto; padding: var(--s-1) 0; scrollbar-width: none; }
.rail-list::-webkit-scrollbar { display: none; }

.rail-item {
  position: relative; display: grid; place-items: center;
  width: 48px; height: 48px; border-radius: var(--r-lg);
  transition: background var(--t-fast) var(--ease);
}
.rail-item:hover { background: var(--surface); }
.rail-item .avatar, .rail-all, .rail-plus { transition: transform var(--t-med) var(--ease-spring); }
.rail-item:hover .avatar, .rail-item:hover .rail-all, .rail-item:hover .rail-plus { transform: scale(1.05); }
.rail-item:active .avatar { transform: scale(0.96); }
.rail-item[data-active="true"]::before {
  content: ""; position: absolute; left: -8px; top: 16px; bottom: 16px; width: 3px;
  border-radius: 99px; background: var(--ink);
}
.rail-item[data-active="true"] { background: var(--surface-2); }

.rail-all {
  display: grid; place-items: center; width: 36px; height: 36px; border-radius: 28%;
  background: var(--surface-2); color: var(--ink-2);
}
.rail-item[data-active="true"] .rail-all { background: var(--surface-3); color: var(--ink); }

.rail-plus {
  display: grid; place-items: center; width: 36px; height: 36px; border-radius: 28%;
  border: 1.5px dashed var(--border-strong); color: var(--ink-3);
}
.rail-add:hover .rail-plus { border-color: var(--ink-2); color: var(--ink); }

.rail-badge {
  position: absolute; top: 4px; right: 4px;
  min-width: 17px; height: 17px; padding: 0 5px; border-radius: 99px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 10.5px; font-weight: 700; line-height: 17px; text-align: center;
  box-shadow: 0 0 0 2px var(--bg);
}
.rail-item[data-active="true"] .rail-badge { box-shadow: 0 0 0 2px var(--surface-2); }
.rail-friend {
  position: absolute; bottom: 6px; right: 6px; width: 8px; height: 8px; border-radius: 50%;
  background: var(--ink-3); box-shadow: 0 0 0 2px var(--bg);
}
.rail-settings { margin-top: auto; }

.list {
  width: 380px; min-width: 320px; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface);
  overflow: hidden;
}
.list-head { padding: var(--s-5) var(--s-4) var(--s-2); display: flex; flex-direction: column; gap: var(--s-3); }
.list-title-row { display: flex; align-items: center; justify-content: space-between; height: 34px; }
.list-title { margin: 0; font-family: var(--font-display); font-size: 20px; font-weight: 700; letter-spacing: -0.02em; }

.compose {
  display: inline-flex; align-items: center; gap: 7px;
  height: 32px; padding: 0 13px 0 11px; border-radius: var(--r-pill);
  background: var(--ink); color: var(--bg); font-weight: 600; font-size: 13px;
  transition: background var(--t-fast), transform var(--t-med) var(--ease-spring);
}
.compose:hover { background: #fff; }
.compose:active { transform: scale(0.97); }

.search {
  display: flex; align-items: center; gap: var(--s-2);
  height: 36px; padding: 0 var(--s-3); border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  border: 1px solid transparent;
  transition: border-color var(--t-fast), background var(--t-fast);
}
.search:focus-within { border-color: var(--border-strong); color: var(--ink-2); }
.search input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); min-width: 0; }
.search input::placeholder { color: var(--ink-3); }

.folders { display: flex; gap: 2px; margin: 0 calc(var(--s-2) * -1); }

.list-scroll { flex: 1; overflow-y: auto; padding: var(--s-1) var(--s-2) var(--s-4); }
.list-empty { padding: 60px 20px; text-align: center; color: var(--ink-3); }

.row {
  position: relative; width: 100%; text-align: left;
  display: flex; gap: var(--s-3); align-items: flex-start;
  padding: var(--s-3) var(--s-3) var(--s-3) var(--s-4); border-radius: var(--r-lg);
  transition: background var(--t-fast) var(--ease);
}
.row:hover { background: var(--surface-2); }
.row[data-selected="true"] { background: var(--surface-3); }
.row .avatar { margin-top: 1px; }
.row-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.row-top { display: flex; align-items: center; gap: var(--s-2); }
.row-from { font-weight: 600; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-from { color: var(--ink); }
.row-count { margin-left: 6px; font-size: 10.5px; font-weight: 600; color: var(--ink-3); background: var(--surface-3); padding: 1px 6px; border-radius: 99px; vertical-align: 1px; }
.row[data-selected="true"] .row-count { background: var(--surface-2); }
.row-time { font-size: 11.5px; color: var(--ink-3); flex-shrink: 0; }
.row-chip {
  font-size: 10.5px; font-weight: 600; padding: 2px 7px; border-radius: 99px; flex-shrink: 0;
  color: var(--a1); background: color-mix(in srgb, var(--a1) 14%, transparent);
}
.row-subject { font-weight: 500; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row[data-unread="true"] .row-subject { font-weight: 650; color: var(--ink); }
.row-preview { font-size: 12.5px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-star { position: absolute; right: 14px; bottom: 14px; color: var(--ink-3); }
.row-dot { position: absolute; left: 6px; top: 50%; width: 5px; height: 5px; margin-top: -2.5px; border-radius: 50%; background: var(--accent); }

.reader {
  flex: 1; min-width: 0; height: 100%;
  display: flex; flex-direction: column;
  background: var(--surface);
  overflow: hidden;
}
.reader-empty { align-items: center; justify-content: center; gap: var(--s-3); color: var(--ink-3); }
.reader-empty-art {
  display: grid; place-items: center; width: 72px; height: 72px; border-radius: 28%;
  background: var(--surface-2); color: var(--ink-3);
}

.reader-bar {
  display: flex; align-items: center; justify-content: space-between;
  height: 34px; margin: var(--s-5) var(--s-6) 0;
}
.reader-account {
  display: inline-flex; align-items: center; gap: var(--s-2);
  height: 30px; padding: 0 var(--s-3) 0 5px; border-radius: var(--r-pill);
  background: var(--surface-2); color: var(--ink-2); font-size: 12.5px; font-weight: 500;
}
.reader-actions { display: flex; gap: 2px; margin-right: 104px; }

/* The conversation: a flat scrolling column, messages are the only cards. */
.thread {
  flex: 1; min-height: 0; overflow-y: auto;
  padding: var(--s-4) var(--s-6) var(--s-6);
  display: flex; flex-direction: column; gap: var(--s-2);
}
.thread-head { flex-shrink: 0; display: flex; flex-direction: column; gap: var(--s-4); padding: var(--s-1) var(--s-1) var(--s-3); }
.reader-subject { margin: 0; font-family: var(--font-display); font-size: 21px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.25; user-select: text; }
.thread-from { display: flex; align-items: center; gap: var(--s-3); }
.thread-from-text { flex: 1; min-width: 0; user-select: text; }
.thread-from-name { font-weight: 650; }
.thread-from-email { font-size: 12px; color: var(--ink-3); }
.thread-count { font-size: 12px; color: var(--ink-3); white-space: nowrap; }

.msg {
  flex-shrink: 0;
  background: var(--surface-2); border-radius: var(--r-lg);
  border: 1px solid var(--border);
  overflow: hidden;
}
.msg-head {
  width: 100%; text-align: left;
  display: flex; align-items: center; gap: var(--s-2);
  padding: var(--s-2) var(--s-4);
  min-height: 40px;
  transition: background var(--t-fast);
}
.msg[data-expanded="false"] .msg-head:hover { background: var(--surface-3); }
.msg-who { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: var(--s-2); overflow: hidden; }
.msg-name { font-weight: 650; white-space: nowrap; }
.msg-snippet { font-size: 12.5px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg-when { font-size: 11.5px; color: var(--ink-3); white-space: nowrap; }
.msg-chevron { color: var(--ink-3); flex-shrink: 0; transition: transform var(--t-med) var(--ease); }
.msg[data-expanded="true"] .msg-chevron { transform: rotate(180deg); }

.msg-body-wrap { position: relative; padding: 0 var(--s-4) var(--s-4); }
.msg-body {
  white-space: pre-wrap; font-size: 14.5px; line-height: 1.6; color: var(--ink);
  max-width: 68ch; user-select: text;
}
.msg-body-wrap[data-clipped="true"] .msg-body {
  max-height: 9.5em; overflow: hidden;
  -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent);
  mask-image: linear-gradient(to bottom, #000 55%, transparent);
}
.msg-more {
  margin-top: var(--s-2); height: 28px; padding: 0 var(--s-3); border-radius: var(--r-pill);
  background: var(--surface-3); color: var(--ink-2); font-weight: 600; font-size: 12.5px;
  transition: background var(--t-fast), color var(--t-fast);
}
.msg-more:hover { color: var(--ink); }

.winctl {
  position: absolute; top: var(--s-2); right: var(--s-2); z-index: 40;
  display: flex; gap: 1px;
  padding: 2px; border-radius: var(--r-md);
  background: var(--surface-2);
}
.winctl-btn {
  display: grid; place-items: center;
  width: 30px; height: 26px; border-radius: var(--r-sm);
  color: var(--ink-3);
  transition: background var(--t-fast), color var(--t-fast);
}
.winctl-btn:hover { background: var(--surface-3); color: var(--ink); }
.winctl-close:hover { background: #c0393f; color: #fff; }

