.sheet-backdrop {
  position: fixed; inset: 0; z-index: 50;
  display: grid; place-items: center;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
  animation: fade var(--t-med) var(--ease);
}
@keyframes fade { from { opacity: 0; } }
@keyframes pop { from { opacity: 0; transform: translateY(10px) scale(0.985); } }

.sheet {
  width: 540px; max-width: calc(100vw - 40px);
  background: var(--surface); border-radius: var(--r-xl);
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-3);
  animation: pop 220ms var(--ease-spring);
  overflow: hidden;
}
.sheet-head { display: flex; align-items: center; justify-content: space-between; padding: var(--s-3) var(--s-3) 0 var(--s-4); }
.sheet-tabs { display: flex; gap: 2px; }
.sheet-body { padding: var(--s-4) var(--s-6) var(--s-6); display: flex; flex-direction: column; gap: var(--s-3); }
.sheet-title { margin: var(--s-1) 0 0; font-family: var(--font-display); font-size: 20px; font-weight: 700; letter-spacing: -0.02em; }
.sheet-hint { margin: 0; color: var(--ink-2); line-height: 1.5; }

.sheet-field {
  display: flex; align-items: center; gap: var(--s-2);
  height: 40px; padding: 0 var(--s-3); border-radius: var(--r-md);
  background: var(--surface-2); color: var(--ink-3);
  border: 1px solid transparent;
  transition: border-color var(--t-fast);
}
.sheet-field:focus-within { border-color: var(--border-strong); }
.sheet-field[data-valid="true"] { border-color: #4f9a68; }
.sheet-field[data-valid="false"] { border-color: #b8484d; }
.sheet-field input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); font-size: 12.5px; min-width: 0; }

.sheet-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--s-2); }
.acct {
  display: flex; align-items: center; gap: var(--s-3); text-align: left;
  padding: var(--s-2) var(--s-3); border-radius: var(--r-md);
  background: var(--surface-2);
  border: 1px solid transparent;
  transition: border-color var(--t-fast), background var(--t-fast);
}
.acct:hover { background: var(--surface-3); }
.acct[data-picked="true"] { border-color: var(--ink-2); }
.acct-text { min-width: 0; }
.acct-name { font-weight: 650; display: flex; align-items: center; gap: 6px; }
.acct-tag { font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--ink-3); background: var(--surface-3); padding: 1px 6px; border-radius: 99px; }
.acct-email { font-size: 12px; color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.primary {
  align-self: flex-end;
  display: inline-flex; align-items: center; gap: var(--s-2);
  height: 38px; padding: 0 var(--s-4) 0 var(--s-5); border-radius: var(--r-pill);
  background: var(--accent); color: var(--accent-ink); font-weight: 600;
  transition: filter var(--t-fast), opacity var(--t-fast);
}
.primary:hover { filter: brightness(1.08); }
.primary:disabled { opacity: 0.35; cursor: not-allowed; }

.providers { display: grid; grid-template-columns: 1fr 1fr; gap: var(--s-2); }
.provider {
  display: flex; align-items: center; gap: var(--s-3);
  height: 52px; padding: 0 var(--s-4); border-radius: var(--r-md);
  background: var(--surface-2); font-weight: 600;
  border: 1px solid transparent;
  transition: background var(--t-fast), border-color var(--t-fast);
}
.provider:hover { background: var(--surface-3); border-color: var(--border-strong); }
.provider-dot { width: 20px; height: 20px; border-radius: 28%; background: linear-gradient(145deg, var(--a1), var(--a2)); }

