1	import { useEffect, useState } from "react";
2	import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
3	import type { Account, Message } from "../data/mock";
4	import { Avatar } from "./Avatar";
5	import { relTime } from "./MailList";
6	import "./Reader.css";
7	
8	interface Props {
9	  /** All messages in the open conversation, newest first. */
10	  thread: Message[];
11	  account: Account | null;
12	}
13	
14	/** Bodies longer than this start clipped with a "Show more" control. */
15	const CLIP_CHARS = 420;
16	
17	export function Reader({ thread, account }: Props) {
18	  const newest = thread[0];
19	  // Which messages are expanded. The newest is open by default; older ones start collapsed.
20	  const [open, setOpen] = useState<Set<string>>(new Set());
21	  useEffect(() => {
22	    setOpen(new Set(newest ? [newest.id] : []));
23	  }, [newest?.threadId]);
24	
25	  if (!newest || !account) {
26	    return (
27	      <section className="reader reader-empty">
28	        <div className="reader-empty-art">
29	          <MailOpen size={38} strokeWidth={1.6} />
30	        </div>
31	        <p>Pick a message to read it here.</p>
32	      </section>
33	    );
34	  }
35	
36	  const toggle = (id: string) =>
37	    setOpen((prev) => {
38	      const next = new Set(prev);
39	      if (next.has(id)) next.delete(id);
40	      else next.add(id);
41	      return next;
42	    });
43	
44	  // The sender shown once at the top. Cards only name a sender when it differs from this.
45	  const primary = newest.from;
46	
47	  return (
48	    <section className="reader">
49	      <header className="reader-bar">
50	        <div className={"reader-account hue-" + account.hue}>
51	          <Avatar name={account.name} hue={account.hue} size={22} />
52	          <span>{account.email}</span>
53	        </div>
54	        <div className="reader-actions">
55	          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
56	          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
57	          <button className="icon-btn" title="Star"><Star size={18} /></button>
58	          <button className="icon-btn" title="Archive"><Archive size={18} /></button>
59	          <button className="icon-btn" title="Delete"><Trash2 size={18} /></button>
60	        </div>
61	      </header>
62	
63	      <div className="thread">
64	        <div className="thread-head">
65	          <h2 className="reader-subject">{newest.subject}</h2>
66	          <div className="thread-from">
67	            <Avatar name={primary.name} hue={account.hue} size={40} />
68	            <div className="thread-from-text">
69	              <div className="thread-from-name">{primary.name}</div>
70	              <div className="thread-from-email">{primary.email}</div>
71	            </div>
72	            {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
73	          </div>
74	        </div>
75	
76	        {thread.map((m) => (
77	          <MessageCard
78	            key={m.id}
79	            message={m}
80	            showSender={m.from.email !== primary.email}
81	            hue={account.hue}
82	            expanded={open.has(m.id)}
83	            onToggle={() => toggle(m.id)}
84	          />
85	        ))}
86	      </div>
87	    </section>
88	  );
89	}
90	
91	interface CardProps {
92	  message: Message;
93	  showSender: boolean;
94	  hue: Account["hue"];
95	  expanded: boolean;
96	  onToggle: () => void;
97	}
98	
99	function MessageCard({ message: m, showSender, hue, expanded, onToggle }: CardProps) {
100	  const [showAll, setShowAll] = useState(false);
101	  const long = m.body.length > CLIP_CHARS;
102	  const date = new Date(m.date);
103	  const fullDate =
104	    date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
105	    " · " +
106	    date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
107	
108	  return (
109	    <article className="msg" data-expanded={expanded}>
110	      <button className="msg-head" onClick={onToggle}>
111	        {showSender && <Avatar name={m.from.name} hue={hue} size={28} />}
112	        <div className="msg-who">
113	          {showSender && <span className="msg-name">{m.from.name}</span>}
114	          {expanded
115	            ? <span className="msg-when">{fullDate}</span>
116	            : <span className="msg-snippet">{m.preview}</span>}
117	        </div>
118	        {!expanded && <span className="msg-when">{relTime(m.date)}</span>}
119	        <ChevronDown size={16} className="msg-chevron" />
120	      </button>
121	
122	      {expanded && (
