22	  --accent-soft: rgba(217, 128, 63, 0.14);
23	
24	  /* Radius scale. Outer surfaces are larger, inner controls smaller. */
25	  --r-xs: 6px;

1	import { useEffect, useLayoutEffect, useRef, useState } from "react";
2	import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
3	import type { Account, Message } from "../data/mock";
4	import { Avatar } from "./Avatar";
5	import { relTime } from "./MailList";
6	import "./Reader.css";
7	
8	interface Props {
9	  /** All messages in the open conversation, newest first. */
10	  thread: Message[];
11	  account: Account | null;
12	}
13	
14	/** Bodies longer than this start clipped with a "Show more" control. */
15	const CLIP_CHARS = 420;
16	
17	export function Reader({ thread, account }: Props) {
18	  const newest = thread[0];
19	  // Which messages are expanded. The newest is open by default; older ones start collapsed.
20	  const [open, setOpen] = useState<Set<string>>(new Set());
21	  useEffect(() => {
22	    setOpen(new Set(newest ? [newest.id] : []));
23	  }, [newest?.threadId]);
24	
25	  if (!newest || !account) {
26	    return (
27	      <section className="reader reader-empty">
28	        <div className="reader-empty-art">
29	          <MailOpen size={38} strokeWidth={1.6} />
30	        </div>
31	        <p>Pick a message to read it here.</p>
32	      </section>
33	    );
34	  }
35	
36	  const toggle = (id: string) =>
37	    setOpen((prev) => {
38	      const next = new Set(prev);
39	      if (next.has(id)) next.delete(id);
40	      else next.add(id);
41	      return next;
42	    });
43	
44	  // The sender shown once at the top. Cards only name a sender when it differs from this.
45	  const primary = newest.from;
46	
47	  return (
48	    <section className="reader">
49	      <header className="reader-bar">
50	        <div className={"reader-account hue-" + account.hue}>
51	          <Avatar name={account.name} hue={account.hue} size={22} />
52	          <span>{account.email}</span>
53	        </div>
54	        <div className="reader-actions">
55	          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
56	          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
57	          <button className="icon-btn" title="Star"><Star size={18} /></button>
58	          <button className="icon-btn" title="Archive"><Archive size={18} /></button>
59	          <button className="icon-btn" title="Delete"><Trash2 size={18} /></button>
60	        </div>
61	      </header>
62	
63	      <div className="thread">
64	        <div className="thread-head">
65	          <h2 className="reader-subject">{newest.subject}</h2>
66	          <div className="thread-from">
67	            <Avatar name={primary.name} hue={account.hue} size={40} />
68	            <div className="thread-from-text">
69	              <div className="thread-from-name">{primary.name}</div>
70	              <div className="thread-from-email">{primary.email}</div>
71	            </div>
72	            {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
73	          </div>
74	        </div>
75	
76	        {thread.map((m) => (
77	          <MessageCard
78	            key={m.id}
79	            message={m}
80	            showSender={m.from.email !== primary.email}
81	            hue={account.hue}
82	            expanded={open.has(m.id)}
83	            onToggle={() => toggle(m.id)}
84	          />
85	        ))}
86	      </div>
87	    </section>
88	  );
89	}
90	
91	interface CardProps {
92	  message: Message;
93	  showSender: boolean;
94	  hue: Account["hue"];
95	  expanded: boolean;
96	  onToggle: () => void;
97	}
98	
99	const CLIP_HEIGHT = "9.5em";
100	
101	function MessageCard({ message: m, showSender, hue, expanded, onToggle }: CardProps) {
102	  const [showAll, setShowAll] = useState(false);
103	  const long = m.body.length > CLIP_CHARS;
104	  const bodyRef = useRef<HTMLDivElement>(null);
105	  // Animate between the clipped height and the body's real height.
106	  useLayoutEffect(() => {
107	    const el = bodyRef.current;
108	    if (!el || !long) return;
109	    el.style.maxHeight = showAll ? el.scrollHeight + "px" : CLIP_HEIGHT;
110	  }, [showAll, long]);
111	  const date = new Date(m.date);
112	  const fullDate =
113	    date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
114	    " · " +
115	    date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
116	
117	  return (
118	    <article className="msg" data-expanded={expanded}>
119	      <button className="msg-head" onClick={onToggle}>
120	        {showSender && <Avatar name={m.from.name} hue={hue} size={28} />}
121	        <div className="msg-who">
122	          {showSender && <span className="msg-name">{m.from.name}</span>}
123	          {expanded
124	            ? <span className="msg-when">{fullDate}</span>
125	            : <span className="msg-snippet">{m.preview}</span>}
126	        </div>
127	        {!expanded && <span className="msg-when">{relTime(m.date)}</span>}
128	        <ChevronDown size={16} className="msg-chevron" />
129	      </button>
130	
131	      <div className="msg-collapse" aria-hidden={!expanded}>
132	        <div>
133	          <div className="msg-body-wrap" data-clipped={long && !showAll}>
134	            <div className="msg-body" ref={bodyRef} data-long={long}>{m.body}</div>
135	            {long && (
136	              <button className="msg-more" onClick={() => setShowAll((v) => !v)} tabIndex={expanded ? 0 : -1}>
137	                {showAll ? "Show less" : "Show more"}
138	              </button>
139	            )}
140	          </div>
141	        </div>
142	      </div>
143	    </article>
144	  );
145	}

