write("src/components/AccountRail.tsx", '''import { useLayoutEffect, useRef, useState } from "react";
import { Inbox, Plus } from "lucide-react";
import type { Account } from "../data/mock";
import { Avatar } from "./Avatar";
import "./AccountRail.css";

interface Props {
  accounts: Account[];
  selected: string | "all";
  onSelect: (id: string | "all") => void;
  onAdd: () => void;
}

export function AccountRail({ accounts, selected, onSelect, onAdd }: Props) {
  const totalUnread = accounts.reduce((n, a) => n + a.unread, 0);
  const listRef = useRef<HTMLDivElement>(null);
  const [glideY, setGlideY] = useState<number | null>(null);

  // The highlight is one element that slides to whichever tile is selected.
  useLayoutEffect(() => {
    const el = listRef.current?.querySelector<HTMLElement>('[data-id="' + selected + '"]');
    setGlideY(el ? el.offsetTop : null);
  }, [selected, accounts.length]);

  return (
    <nav className="rail">
      <div className="rail-list" ref={listRef}>
        {glideY !== null && <span className="rail-glide" style={{ transform: "translateY(" + glideY + "px)" }} />}

        <button className="rail-item" data-id="all" data-active={selected === "all"} onClick={() => onSelect("all")} title="All inboxes">
          <Inbox size={22} strokeWidth={2} className="rail-all" />
          {totalUnread > 0 && <span className="rail-badge">{totalUnread}</span>}
        </button>

        <div className="rail-sep" />

        {accounts.map((a) => (
          <button key={a.id} className="rail-item" data-id={a.id} data-active={selected === a.id} onClick={() => onSelect(a.id)} title={a.name + " · " + a.email}>
            <Avatar name={a.name} hue={a.hue} size={36} />
            {a.unread > 0 && <span className="rail-badge">{a.unread}</span>}
          </button>
        ))}

        <button className="rail-item rail-add" onClick={onAdd} title="Add account or sign in with Google">
          <Plus size={22} strokeWidth={2.2} className="rail-plus" />
        </button>
      </div>
    </nav>
  );
}
''')
