input.content:
.rail {
  width: 72px; height: 100%;
  display: flex; flex-direction: column; align-items: center;
  padding: 10px; gap: var(--s-1);
  background: var(--bg);
}
.rail-list {
  position: relative;
  display: flex; flex-direction: column; align-items: center; gap: var(--s-1);
  flex: 1; overflow-y: auto; width: 100%;
  scrollbar-width: none;
}
.rail-list::-webkit-scrollbar { display: none; }

/* One sliding highlight sits behind the selected account tile (accounts only). */
.rail-glide {
  position: absolute; left: 0; top: 0; width: 52px; height: 52px;
  border-radius: var(--r-lg);
  background: #4a4541;
  box-shadow: inset 0 0 0 1px rgba(255, 245, 230, 0.22);
  transition: transform 320ms var(--ease-spring);
  pointer-events: none;
}

/* Tiles are plain 52px squares; nothing about them changes size on selection. */
.rail-item {
  position: relative; z-index: 1; flex-shrink: 0;
  display: grid; place-items: center;
  width: 52px; height: 52px; border-radius: var(--r-lg);
  transition: background var(--t-fast) var(--ease);
}
.rail-item:hover { background: var(--surface); }
.rail-item[data-active="true"] { background: transparent; }

/* Account avatars: 36px, and 38px when selected (inside the shell). */
.rail-item .avatar { transition: transform 260ms var(--ease-spring); }
.rail-item[data-active="true"] .avatar { transform: scale(1.055); }

/* All inboxes: a 36px tinted square that turns white when selected, at the same 38px as a
   selected avatar. It never gets the shell. */
.rail-all {
  width: 36px; height: 36px; padding: 8px; border-radius: 28%;
  background: var(--surface-2); color: var(--ink-2);
  transition: transform 260ms var(--ease-spring), background 200ms var(--ease), color var(--t-fast);
}
.rail-item[data-active="true"] .rail-all { background: var(--ink); color: var(--bg); transform: scale(1.055); }

.rail-sep { width: 32px; height: 1px; background: var(--line-strong); margin: var(--s-1) 0; flex-shrink: 0; }

/* The plus fills its whole tile, the same footprint as a selected tile, with a visible dashed edge. */
.rail-plus {
  width: 52px; height: 52px; padding: 14px; border-radius: var(--r-lg);
  border: 1.5px dashed rgba(255, 245, 230, 0.3); color: var(--ink-2);
  transition: border-color var(--t-fast), color var(--t-fast), background var(--t-fast);
}
.rail-add:hover .rail-plus { border-color: rgba(255, 245, 230, 0.5); color: var(--ink); background: var(--surface); }

.rail-badge {
  position: absolute; top: 4px; right: 4px;
  min-width: 17px; height: 17px; padding: 0 5px; border-radius: 99px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 10.5px; font-weight: 700; line-height: 17px; text-align: center;
  box-shadow: 0 0 0 2px var(--bg);
}

