// Thin typed layer over the Rust commands. Components only ever talk to this.
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

export type Hue = "coral" | "sun" | "leaf" | "sky" | "grape" | "mint" | "rose" | "slate";

export interface Account {
  id: string;
  name: string;
  email: string;
  provider: "gmail" | "outlook" | "imap";
  hue: Hue;
  unread: number;
}

export type Folder = "inbox" | "starred" | "sent" | "archive";

export interface Message {
  id: number;
  accountId: string;
  folder: "inbox" | "sent";
  threadId: string;
  subject: string;
  from: { name: string; email: string };
  preview: string;
  /** Plain text body; empty in list results. */
  body: string;
  /** Sanitized HTML body; empty in list results or if the mail had none. */
  html: string;
  /** ISO timestamp. */
  date: string;
  unread: boolean;
  starred: boolean;
}

/** A conversation is identified per account; thread ids are only unique within one mailbox. */
export type ThreadRef = { accountId: string; threadId: string };
export const threadKey = (m: { accountId: string; threadId: string }) => m.accountId + "�" + m.threadId;

interface RawMessage {
  id: number;
  accountId: string;
  folder: "inbox" | "sent";
  uid: number;
  threadId: string;
  subject: string;
  fromName: string;
  fromEmail: string;
  date: number;
  snippet: string;
  textBody: string;
  htmlBody: string;
  unread: boolean;
  starred: boolean;
}

function fromRaw(r: RawMessage): Message {
  return {
    id: r.id,
    accountId: r.accountId,
    folder: r.folder,
    threadId: r.threadId,
    subject: r.subject,
    from: { name: r.fromName, email: r.fromEmail },
    preview: r.snippet,
    body: r.textBody,
    html: r.htmlBody,
    date: new Date(r.date).toISOString(),
    unread: r.unread,
    starred: r.starred,
  };
}

export interface SyncReport { accountId: string; added: number; error: string | null }

export const api = {
  listAccounts: () => invoke<Account[]>("list_accounts"),
  addGmail: (name: string, email: string, appPassword: string) =>
    invoke<Account>("add_gmail_account", { name, email, appPassword }),
  removeAccount: (accountId: string) => invoke<void>("remove_account", { accountId }),
  sync: (accountId?: string) => invoke<SyncReport[]>("sync_mail", { accountId: accountId ?? null }),
  listMessages: async (accountId?: string) =>
    (await invoke<RawMessage[]>("list_messages", { accountId: accountId ?? null })).map(fromRaw),
  getThread: async (accountId: string, threadId: string) =>
    (await invoke<RawMessage[]>("get_thread", { accountId, threadId })).map(fromRaw),
  markRead: (id: number, read: boolean) => invoke<void>("mark_read", { id, read }),
  setStarred: (id: number, starred: boolean) => invoke<void>("set_starred", { id, starred }),
  /** "archive" moves to All Mail, "trash" to Trash. */
  move: (id: number, to: "archive" | "trash") => invoke<void>("move_message", { id, to }),
  onUpdated: (cb: () => void): Promise<UnlistenFn> => listen("mail:updated", cb),
};

