      <div className="app">
        <WindowControls maximized={maximized} />
        <AccountRail
          accounts={accounts}
          selected={selectedAccount}
          onSelect={setSelectedAccount}
          onAdd={() => setSheet(true)}
        />
        <main className="main">
          <MailList
            viewKey={selectedAccount + ":" + folder + ":" + refreshTick}
            title={title}
            syncing={syncing}
            accountsById={accountsById}
            rows={rows}
            folder={folder}
            onFolder={setFolder}
            selectedKey={selected ? threadKey(selected) : null}
            onSelect={(m) => setSelected({ accountId: m.accountId, threadId: m.threadId })}
            showAccountChip={selectedAccount === "all"}
            hasAccounts={accounts.length > 0}
            onAdd={() => setSheet(true)}
          />
          <Reader thread={thread} account={account} onStar={onStar} onMove={onMove} />
        </main>
        {sheet && (
          <AddSheet
            accounts={accounts}
            closeSignal={sheetClose}
            onClose={() => { setSheet(false); setSheetClose(0); }}
            onAdded={() => reload()}
          />
        )}
      </div>
    </div>
  );
}

import { Search, Star, PenLine, Loader2, Plus } from "lucide-react";
