          <div className="msg-body-wrap" data-clipped={long && !showAll}>
            {isHtml
              ? (expanded ? <HtmlBody html={m.html} /> : null)
              : <div className="msg-body" ref={bodyRef} data-long={long}>{m.body}</div>}
            {long && (
              <button className="msg-more" onClick={() => setShowAll((v) => !v)} tabIndex={expanded ? 0 : -1}>
                {showAll ? "Show less" : "Show more"}
              </button>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

/** Renders sanitized email HTML in an isolated, script-free frame sized to its content. */
function HtmlBody({ html }: { html: string }) {
  const ref = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(120);
  const doc =
    "<!doctype html><html><head><meta charset='utf-8'><base target='_blank'>" +
    "<style>" +
    "@font-face{font-family:Poppins;font-weight:400;src:url('/fonts/poppins-400.woff2') format('woff2')}" +
    "@font-face{font-family:Poppins;font-weight:600;src:url('/fonts/poppins-600.woff2') format('woff2')}" +
    "html,body{margin:0;padding:0;background:transparent}" +
    "body{font-family:Poppins,'Segoe UI',sans-serif;font-size:14px;line-height:1.55;color:#ece7df;overflow-wrap:anywhere}" +
    "img{max-width:100%;height:auto} a{color:#8fb4ff} table{max-width:100%}" +
    "</style></head><body>" + html + "</body></html>";

  const fit = () => {
    const d = ref.current?.contentDocument;
    if (d) setHeight(Math.min(20000, Math.max(40, d.documentElement.scrollHeight)));
  };
  useEffect(() => {
    // Images finish loading after onload; re-measure a couple of times.
    const t1 = window.setTimeout(fit, 300);
    const t2 = window.setTimeout(fit, 1500);
    return () => { window.clearTimeout(t1); window.clearTimeout(t2); };
  }, [html]);

  return (
    <iframe
      ref={ref}
      className="msg-html"
      title="Message"
      sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox"
      srcDoc={doc}
      style={{ height }}
      onLoad={fit}
    />
  );
}

