import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { Archive, Reply, Star, Trash2, MailOpen, Forward, ChevronDown } from "lucide-react";
import type { Account, Message } from "../data/mock";
import { Avatar } from "./Avatar";
import { relTime } from "./MailList";
import "./Reader.css";

interface Props {
  /** All messages in the open conversation, newest first. */
  thread: Message[];
  account: Account | null;
}

/** Bodies longer than this start clipped with a "Show more" control. */
const CLIP_CHARS = 420;

export function Reader({ thread, account }: Props) {
  const newest = thread[0];
  // Which messages are expanded. The newest is open by default; older ones start collapsed.
  const [open, setOpen] = useState<Set<string>>(new Set());
  useEffect(() => {
    setOpen(new Set(newest ? [newest.id] : []));
  }, [newest?.threadId]);

  if (!newest || !account) {
    return (
      <section className="reader reader-empty">
        <div className="reader-empty-art">
          <MailOpen size={38} strokeWidth={1.6} />
        </div>
        <p>Pick a message to read it here.</p>
      </section>
    );
  }

  const toggle = (id: string) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  // The sender shown once at the top. Cards only name a sender when it differs from this.
  const primary = newest.from;

  return (
    <section className="reader">
      <header className="reader-bar">
        <div className={"reader-account hue-" + account.hue}>
          <Avatar name={account.name} hue={account.hue} size={22} />
          <span>{account.email}</span>
        </div>
        <div className="reader-actions">
          <button className="icon-btn" title="Reply"><Reply size={18} /></button>
          <button className="icon-btn" title="Forward"><Forward size={18} /></button>
          <button className="icon-btn" title="Star"><Star size={18} /></button>
          <button className="icon-btn" title="Archive"><Archive size={18} /></button>
          <button className="icon-btn" title="Delete"><Trash2 size={18} /></button>
        </div>
      </header>

      <div className="thread">
        <div className="thread-head">
          <h2 className="reader-subject">{newest.subject}</h2>
          <div className="thread-from">
            <Avatar name={primary.name} hue={account.hue} size={40} />
            <div className="thread-from-text">
              <div className="thread-from-name">{primary.name}</div>
              <div className="thread-from-email">{primary.email}</div>
            </div>
            {thread.length > 1 && <span className="thread-count">{thread.length} messages</span>}
          </div>
        </div>

        {thread.map((m) => (
          <MessageCard
            key={m.id}
            message={m}
            showSender={m.from.email !== primary.email}
            hue={account.hue}
            expanded={open.has(m.id)}
            onToggle={() => toggle(m.id)}
          />
        ))}
      </div>
    </section>
  );
}

interface CardProps {
  message: Message;
  showSender: boolean;
  hue: Account["hue"];
  expanded: boolean;
  onToggle: () => void;
}

const CLIP_HEIGHT = "9.5em";

function MessageCard({ message: m, showSender, hue, expanded, onToggle }: CardProps) {
  const [showAll, setShowAll] = useState(false);
  const long = m.body.length > CLIP_CHARS;
  const bodyRef = useRef<HTMLDivElement>(null);
  // Animate between the clipped height and the body's real height.
  useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el || !long) return;
    el.style.maxHeight = showAll ? el.scrollHeight + "px" : CLIP_HEIGHT;
  }, [showAll, long]);
  const date = new Date(m.date);
  const fullDate =
    date.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" }) +
    " · " +
    date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });

  return (
    <article className="msg" data-expanded={expanded}>
      <button className="msg-head" onClick={onToggle}>
        {showSender && <Avatar name={m.from.name} hue={hue} size={28} />}
        <div className="msg-who">
          {showSender && <span className="msg-name">{m.from.name}</span>}
          {expanded
            ? <span className="msg-when">{fullDate}</span>
            : <span className="msg-snippet">{m.preview}</span>}
        </div>
        <span className="msg-when">{relTime(m.date)}</span>
        <ChevronDown size={16} className="msg-chevron" />
      </button>

      <div className="msg-collapse" aria-hidden={!expanded}>
        <div>
          <div className="msg-body-wrap" data-clipped={long && !showAll}>
            <div className="msg-body" ref={bodyRef} data-long={long}>{m.body}</div>
            {long && (
              <button className="msg-more" onClick={() => setShowAll((v) => !v)} tabIndex={expanded ? 0 : -1}>
                {showAll ? "Show less" : "Show more"}
              </button>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

