import { useEffect, useMemo, useRef, useState } from "react";
import { accounts, messages, type Message } from "./data/mock";
import { AccountRail } from "./components/AccountRail";
import { MailList } from "./components/MailList";
import { Reader } from "./components/Reader";
import { AddSheet } from "./components/AddSheet";
import { WindowControls, useMaximized, useWindowDrag } from "./components/WindowControls";
import "./styles/base.css";
import "./App.css";

type Folder = Message["folder"];

export default function App() {
  const [selectedAccount, setSelectedAccount] = useState<string | "all">("all");
  const [folder, setFolder] = useState<Folder>("inbox");
  const [selectedThread, setSelectedThread] = useState<string | null>(null);
  const [sheet, setSheet] = useState(false);
  const [sheetClose, setSheetClose] = useState(0);
  const sheetRef = useRef(false);
  sheetRef.current = sheet;
  const [refreshTick, setRefreshTick] = useState(0);
  const maximized = useMaximized();
  useWindowDrag(maximized);

  // App-level keys: Esc closes the open conversation; browser reload/nav keys do nothing here.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const inField = (e.target as HTMLElement | null)?.closest("input, textarea, [contenteditable]");
      if (e.key === "Escape") {
        // The sheet closes on Escape even while typing in its field. Otherwise Escape closes the email,
        // unless the user is in a text field.
        if (sheetRef.current) { setSheetClose((n) => n + 1); return; }
        if (!inField) { setSelectedThread(null); return; }
      }
      const reload = e.key === "F5" || ((e.ctrlKey || e.metaKey) && (e.key === "r" || e.key === "R"));
      const nav = e.altKey && (e.key === "ArrowLeft" || e.key === "ArrowRight");
      if (reload) {
        // Never reload the page. Replay the list instead (and, once sync exists, poll the server).
        e.preventDefault();
        setRefreshTick((t) => t + 1);
        return;
      }
      if (nav || e.key === "BrowserBack" || e.key === "BrowserForward") e.preventDefault();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const accountsById = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a])), []);

  // Messages that belong to the current account + folder, newest first.
  const scoped = useMemo(() => {
    return messages
      .filter((m) => selectedAccount === "all" || m.accountId === selectedAccount)
      .filter((m) => (folder === "starred" ? m.starred : m.folder === folder))
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [selectedAccount, folder]);

  // The list shows one row per conversation: its newest message, plus how many are in it.
  const rows = useMemo(() => {
    const seen = new Map<string, { latest: Message; count: number; unread: boolean }>();
    for (const m of scoped) {
      const t = seen.get(m.threadId);
      if (t) { t.count += 1; t.unread ||= m.unread; }
      else seen.set(m.threadId, { latest: m, count: 1, unread: m.unread });
    }
    return [...seen.values()];
  }, [scoped]);

  // The open conversation is independent of the folder filter, so switching folders
  // doesn't close what you're reading. Only changing account clears it.
  const thread = useMemo(
    () =>
      selectedThread
        ? messages.filter((m) => m.threadId === selectedThread).sort((a, b) => b.date.localeCompare(a.date))
        : [],
    [selectedThread],
  );
  const account = thread[0] ? accountsById[thread[0].accountId] : null;
  const title = selectedAccount === "all" ? "All Inboxes" : accountsById[selectedAccount].name;

  return (
    <div className="frame" data-maximized={maximized}>
      <div className="app">
        <WindowControls maximized={maximized} />
        <AccountRail
          accounts={accounts}
          selected={selectedAccount}
          onSelect={setSelectedAccount}
          onAdd={() => setSheet(true)}
        />
        <main className="main">
          <MailList
            viewKey={selectedAccount + ":" + folder + ":" + refreshTick}
            title={title}
            accountsById={accountsById}
            rows={rows}
            folder={folder}
            onFolder={setFolder}
            selectedId={selectedThread}
            onSelect={setSelectedThread}
            showAccountChip={selectedAccount === "all"}
          />
          <Reader thread={thread} account={account} />
        </main>
        {sheet && <AddSheet accounts={accounts} closeSignal={sheetClose} onClose={() => { setSheet(false); setSheetClose(0); }} />}
      </div>
    </div>
  );
}

