//! Per-account Google sessions. Each account gets its own WebView2 profile (its own cookie jar)
//! so it stays logged into Google independently of every other account and of the user's browser.
//!
//! Two uses:
//!   1. Adding an account: open Google's app-password page in that profile. Logging in there
//!      creates the persistent session; the app password is created on that same page.
//!   2. "Sign in with Google" chooser: open a site's Google OAuth URL in the chosen account's
//!      profile. Google finishes the login with that account and redirects to the site's callback;
//!      we catch that navigation, hand the callback URL to the user's real browser (where the
//!      site session lives), and close.

use crate::mail::account_id_for;
use tauri::{AppHandle, Manager, Url, WebviewUrl, WebviewWindowBuilder};
use tauri_plugin_opener::OpenerExt;

const APP_PASSWORDS_URL: &str = "https://myaccount.google.com/apppasswords";

/// Hosts the Google login [REDACTED] bounces through. Anything else is the site's callback.
fn is_google(host: &str) -> bool {
    const ALLOW: &[&str] = &[
        "google.com",
        "googleusercontent.com",
        "gstatic.com",
        "googleapis.com",
        "youtube.com",
        "ggpht.com",
        "googlevideo.com",
        "gvt1.com",
        "recaptcha.net",
    ];
    ALLOW.iter().any(|d| host == *d || host.ends_with(&format!(".{d}")))
}

pub fn profile_dir(app: &AppHandle, account_id: &str) -> Result<std::path::PathBuf, String> {
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| e.to_string())?
        .join("profiles")
        .join(account_id);
    std::fs::create_dir_all(&dir).map_err(|e| e.to_string())?;
    Ok(dir)
}

/// Open (or focus) the Google window for `email`'s profile at `url`, defaulting to the
/// app-passwords page. Non-Google navigations are bounced to the system browser.
#[tauri::command]
pub async fn open_google(app: AppHandle, email: String, url: Option<String>) -> Result<(), String> {
    let email = email.trim().to_lowercase();
    let id = account_id_for(&email);
    let label = format!("google-{id}");
    let target = Url::parse(url.as_deref().unwrap_or(APP_PASSWORDS_URL)).map_err(|e| format!("Bad link: {e}"))?;

    if let Some(w) = app.get_webview_window(&label) {
        w.navigate(target).map_err(|e| e.to_string())?;
        let _ = w.set_focus();
        return Ok(());
    }

    let dir = profile_dir(&app, &id)?;
    let bounce_app = app.clone();
    let bounce_label = label.clone();

    WebviewWindowBuilder::new(&app, &label, WebviewUrl::External(target))
        .title(format!("Google · {email}"))
        .inner_size(520.0, 780.0)
        .min_inner_size(400.0, 500.0)
        .center()
        .data_directory(dir)
        .on_navigation(move |u| {
            let host = u.host_str().unwrap_or("");
            if u.scheme() == "about" || u.scheme() == "blob" || u.scheme() == "data" || is_google(host) {
                return true;
            }
            // The site's callback (https://site/cb?code=…, http://127.0.0.1:port/…, or a custom
            // scheme). Deliver it to the real browser / the waiting desktop app, then close.
            let _ = bounce_app.opener().open_url(u.to_string(), None::<&str>);
            if let Some(w) = bounce_app.get_webview_window(&bounce_label) {
                std::thread::spawn(move || {
                    let _ = w.close();
                });
            }
            false
        })
        .build()
        .map_err(|e| format!("Could not open the Google window: {e}"))?;
    Ok(())
}

/// Forget an account's Google session entirely.
pub fn remove_profile(app: &AppHandle, account_id: &str) {
    if let Ok(dir) = profile_dir(app, account_id) {
        let _ = std::fs::remove_dir_all(dir);
    }
}

