17	pub(crate) fn account_id_for(email: &str) -> String {
18	    // Stable, filesystem/keyring safe id derived from the address.
19	    let mut h: u64 = 1469598103934665603;
20	    for b in email.trim().to_lowercase().bytes() {
21	        h ^= b as u64;
22	        h = h.wrapping_mul(1099511628211);
23	    }
24	    format!("acct_{h:016x}")
25	}
