37	/// Sync every folder we care about for one account. Blocking; run on a worker thread.
38	fn sync_account_blocking(db: &Arc<Mutex<Connection>>, account: &db::AccountRow) -> Result<usize, String> {
39	    let password = password_for(&account.id)?;
40	    let mut session = gmail::connect(&account.imap_host, account.imap_port, &account.email, &password)?;
41	    let folders = gmail::discover_folders(&mut session)?;
42	
43	    let mut targets = vec![(folders.inbox.clone(), "inbox".to_string())];
44	    if let Some(sent) = &folders.sent {
45	        targets.push((sent.clone(), "sent".to_string()));
46	    }
47	
48	    let mut added = 0;
49	    for (server_folder, our_folder) in targets {
50	        let prev = db::sync_state(&lock(db), &account.id, &our_folder).map_err(|e| e.to_string())?;
51	        let result = gmail::sync_folder(&mut session, &server_folder, &our_folder, prev)?;
52	        let fresh = !matches!(prev, Some((v, _)) if v == result.uid_validity);
53	        let mut conn = lock(db);
54	        if fresh {
55	            db::clear_folder(&conn, &account.id, &our_folder).map_err(|e| e.to_string())?;
56	        } else {
57	            db::retain_uids(&conn, &account.id, &our_folder, &result.live_uids).map_err(|e| e.to_string())?;
58	            db::update_flags(&mut conn, &account.id, &our_folder, &result.flags).map_err(|e| e.to_string())?;
59	        }
60	        added += result.new.len();
61	        db::upsert_messages(&mut conn, &account.id, &result.new).map_err(|e| e.to_string())?;
62	        db::set_sync_state(&conn, &account.id, &our_folder, result.uid_validity, result.last_uid).map_err(|e| e.to_string())?;
63	    }
64	    let _ = session.logout();
65	    Ok(added)
66	}
