100	    }
101	    if password.len() != 16 {
102	        return Err("A Google app password is 16 letters. Copy it exactly as Google shows it.".into());
103	    }
104	    let name = if name.trim().is_empty() { email.split('@').next().unwrap_or("Account").to_string() } else { name.trim().to_string() };
105	
106	    let account = tauri::async_runtime::spawn_blocking(move || -> Result<db::Account, String> {
107	        // 1. prove the credentials work
108	        let mut session = gmail::connect(GMAIL_HOST, GMAIL_PORT, &email, &password)?;
109	        let _ = session.logout();
110	        // 2. store the secret in the OS credential manager, never in our database
111	        let id = account_id_for(&email);
112	        keyring::Entry::new(KEYRING_SERVICE, &id)
113	            .and_then(|e| e.set_password(&password))
114	            .map_err(|e| format!("Could not save the password to Windows Credential Manager: {e}"))?;
115	        // 3. record the account
116	        {
117	            let conn = lock(&db);
118	            db::insert_account(&conn, &id, &name, &email, "gmail", GMAIL_HOST, GMAIL_PORT).map_err(|e| {
119	                if e.to_string().contains("UNIQUE") { "That account is already connected.".to_string() } else { e.to_string() }
120	            })?;
121	        }
122	        // 4. first sync
123	        let row = db::get_account(&lock(&db), &id).map_err(|e| e.to_string())?.ok_or("account vanished")?;
124	        sync_account_blocking(&db, &row)?;
