153	/// Sync all accounts (or one). Emits `mail:updated` when done. Errors are per account.
154	#[tauri::command]
155	pub async fn sync_mail(app: AppHandle, state: State<'_, MailState>, account_id: Option<String>) -> Result<Vec<SyncReport>, String> {
156	    let db = state.db.clone();
157	    let reports = tauri::async_runtime::spawn_blocking(move || -> Result<Vec<SyncReport>, String> {
158	        let rows = match &account_id {
159	            Some(id) => db::get_account(&lock(&db), id).map_err(|e| e.to_string())?.into_iter().collect(),
160	            None => db::all_account_rows(&lock(&db)).map_err(|e| e.to_string())?,
161	        };
162	        let mut reports = Vec::new();
163	        for row in rows {
164	            let r = sync_account_blocking(&db, &row);
165	            reports.push(SyncReport {
166	                account_id: row.id.clone(),
167	                added: *r.as_ref().unwrap_or(&0),
168	                error: r.err(),
169	            });
170	        }
171	        Ok(reports)
172	    })
173	    .await
174	    .map_err(|e| e.to_string())??;
175	    let _ = app.emit("mail:updated", ());
176	    Ok(reports)
177	}
